    private void validateConfiguration() {
        if (endpoint == null || endpoint.trim().isEmpty()) {
            throw new IllegalStateException(
                "OSS endpoint is not configured. Set oss.endpoint in oss-config.properties " +
                "or OSS_ENDPOINT environment variable");
        }
        if (accessKeyId == null || accessKeyId.trim().isEmpty()) {
            throw new IllegalStateException(
                "OSS access key ID is not configured. Set oss.accessKeyId in oss-config.properties " +
                "or OSS_ACCESS_KEY_ID environment variable");
        }
        if (accessKeySecret == null || accessKeySecret.trim().isEmpty()) {
            throw new IllegalStateException(
                "OSS access key secret is not configured. Set oss.accessKeySecret in oss-config.properties " +
                "or OSS_ACCESS_KEY_SECRET environment variable");
        }
        if (bucketName == null || bucketName.trim().isEmpty()) {
            throw new IllegalStateException(
                "OSS bucket name is not configured. Set oss.bucketName in oss-config.properties " +
                "or OSS_BUCKET_NAME environment variable");
        }
    }

    /**
     * Shuts down the OSS client and releases resources.
     * Should be called when the service is no longer needed.
     */
    public void shutdown() {
        if (ossClient != null) {
            ossClient.shutdown();
        }
    }
}
